namespace {

const int kStripW  = 440;
const int kStripX  = (640 - kStripW) / 2;
const int kDirtY   = 392;
const int kGrassY  = kDirtY - 30;

GRRLIB_texImg* s_bg = NULL;
GRRLIB_texImg* s_logo = NULL;
GRRLIB_texImg* s_grass = NULL;
GRRLIB_texImg* s_dirt = NULL;
GRRLIB_texImg* s_stem = NULL;
GRRLIB_texImg* s_stemShort = NULL;
bool  s_loaded = false;
float s_lastDrawn = -1.0f;

void EnsureLoaded(void)
{
    if (s_loaded) return;
    s_loaded = true;
    s_bg        = GRRLIB_LoadTexture(kLoad_bg);
    s_logo      = GRRLIB_LoadTexture(kLoad_logo);
    s_grass     = GRRLIB_LoadTexture(kLoad_grass);
    s_dirt      = GRRLIB_LoadTexture(kLoad_dirt);
    s_stem      = GRRLIB_LoadTexture(kLoad_stem);
    s_stemShort = GRRLIB_LoadTexture(kLoad_stemShort);
}

/* Explicit screen-space quad: (x,y) = top-left, size (w,h). */
void DrawTex(GRRLIB_texImg* t, float x, float y, float w, float h)
{
    if (!t || !t->data) return;
    guVector q[4] = { {x, y, 0}, {x + w, y, 0}, {x + w, y + h, 0}, {x, y + h, 0} };
    GRRLIB_DrawImgQuad(q, t, 0xFFFFFFFF);
}

/* Left part (revealW pixels) of a strip texture drawn 1:1 at (x,y). */
void DrawStripPart(GRRLIB_texImg* t, int x, int y, int revealW)
{
    if (!t || !t->data || revealW <= 0) return;
    if (revealW > (int)t->w) revealW = (int)t->w;
    GRRLIB_DrawPart((f32)x, (f32)y, 0.0f, 0.0f, (f32)revealW, (f32)t->h, t, 0.0f, 1.0f, 1.0f, 0xFFFFFFFF);
}

/* Sprout whose base sits on (cx, baseY); `grow` 0..1 is its pop-in progress. */
void DrawSprout(GRRLIB_texImg* t, float cx, float baseY, float size, float grow)
{
    if (!t || !t->data || grow <= 0.0f) return;
    /* ease-out with a little overshoot, so it "pops" out of the soil */
    float g = grow >= 1.0f ? 1.0f : 1.0f - (1.0f - grow) * (1.0f - grow);
    if (grow < 1.0f) g *= 1.0f + 0.12f * sinf(grow * 3.14159265f);
    float w = (float)t->w * size * g, h = (float)t->h * size * g;
    DrawTex(t, cx - w * 0.5f, baseY - h, w, h);
}

} /* namespace */

void Loading_Set(float p)
{
    if (p < 0.0f) p = 0.0f;
    if (p > 1.0f) p = 1.0f;
    /* Every GRRLIB_Render() waits for vsync; don't pay that 150 times. */
    if (p < 1.0f && s_lastDrawn >= 0.0f && p - s_lastDrawn < 0.02f) return;
    s_lastDrawn = p;
    EnsureLoaded();

    GRRLIB_Rectangle(0, 0, 640, 480, 0x1A0F05FF, true);
    if (s_bg && s_bg->data)
        DrawTex(s_bg, 0.0f, 0.0f, 640.0f, 480.0f);
    if (s_logo && s_logo->data)
        DrawTex(s_logo, (640.0f - (float)s_logo->w) * 0.5f, 14.0f, (float)s_logo->w, (float)s_logo->h);

    /* soil + grass revealed left to right */
    int reveal = (int)(p * (float)kStripW + 0.5f);
    DrawStripPart(s_dirt,  kStripX, kDirtY,  reveal);
    DrawStripPart(s_grass, kStripX, kGrassY, reveal);
    if (!(s_dirt && s_dirt->data))   /* fallback bar if the art failed to decode */
        GRRLIB_Rectangle((f32)kStripX, (f32)kDirtY, (f32)reveal, 28.0f, 0xC8782AFF, true);

    /* one sprout per completed quarter, each bigger than the last */
    static const float kSize[4] = { 0.70f, 0.55f, 0.75f, 1.00f };
    for (int q = 1; q <= 4; ++q)
    {
        float at = 0.25f * (float)q;
        if (p + 0.0001f < at) break;
        float grow = (p - at) / 0.10f;            /* pops in over the next 10 % */
        float cx = (float)kStripX + (float)kStripW * at - (q == 4 ? 34.0f : 0.0f);
        DrawSprout(q == 1 ? s_stemShort : s_stem, cx, (float)kGrassY + 34.0f, kSize[q - 1], grow);
    }

    GRRLIB_Render();
}

void Loading_Finish(void)
{
    if (s_bg)        GRRLIB_FreeTexture(s_bg);
    if (s_logo)      GRRLIB_FreeTexture(s_logo);
    if (s_grass)     GRRLIB_FreeTexture(s_grass);
    if (s_dirt)      GRRLIB_FreeTexture(s_dirt);
    if (s_stem)      GRRLIB_FreeTexture(s_stem);
    if (s_stemShort) GRRLIB_FreeTexture(s_stemShort);
    s_bg = s_logo = s_grass = s_dirt = s_stem = s_stemShort = NULL;
    s_loaded = false;
    s_lastDrawn = -1.0f;
}
